    generation: 0,
    feedback: '',
    loadNotice: '',
    announcement: 0,
    celebration: false,
    preferences,
  };
}

export function replaceGame(session: Session, game: GameState, imported: boolean): Session {
  const nextGame = imported ? game : { ...game, name: '' };
  const paused = imported && !isWon(nextGame);
  const loadNotice = imported
    ? paused
      ? SessionNotice.loaded
      : SessionNotice.loadedCompleted
    : '';
  return {
    ...session,
    game: nextGame,
    paused,
    generation: session.generation + 1,
    celebration: false,
